def solve(path):
    """Simplify a Unix-style absolute path.
    Handles '.' (current directory), '..' (parent directory), multiple slashes,
    and removes any trailing slash unless the result is the root '/'.
    """
    # If path is empty or not a string, return root as fallback
    if not isinstance(path, str) or not path:
        return '/'
    # Split by '/', filter out empty parts caused by consecutive slashes
    parts = path.split('/')
    stack = []
    for part in parts:
        if part == '' or part == '.':
            # Skip empty components (due to leading, trailing, or multiple slashes) and current dir
            continue
        if part == '..':
            # Go up one level if possible
            if stack:
                stack.pop()
            # If stack empty, stay at root
        else:
            stack.append(part)
    # Build the simplified path
    if not stack:
        return '/'
    return '/' + '/'.join(stack)

