def solve(path: str) -> str:
    """Simplify an absolute Unix path.
    - Collapse consecutive slashes.
    - Resolve '.' and '..' components.
    - Return '/' for root.
    """
    parts = path.split('/')
    stack = []
    for part in parts:
        if not part or part == '.':
            continue
        if part == '..':
            if stack:
                stack.pop()
        else:
            stack.append(part)
