def solve(lst):
    """Flatten a nested list of integers.
    Uses an explicit stack to avoid recursion depth limits.
    """
    result = []
    stack = [iter(lst)]
    while stack:
        try:
            item = next(stack[-1])
        except StopIteration:
            stack.pop()
            continue
        if isinstance(item, list):
            stack.append(iter(item))
        else:
            result.append(item)
    return result

