def solve(nums):
    """Return length of longest strictly increasing subsequence.
    If input is not a list/iterable of numbers, return 0.
    """
    try:
        iterator = iter(nums)
    except TypeError:
        return 0
    from bisect import bisect_left
    tails = []
    for x in nums:
        # Ensure x is comparable; if not, skip
        try:
            i = bisect_left(tails, x)
        except Exception:
            continue
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)

def solve(path):
    """Simplify a Unix‑style absolute path.
    * If *path* is not a string, return an empty string.
    * An empty string also returns an empty string.
    * The function resolves '.' and '..', removes duplicate slashes and any
      trailing slash (except when the result is the root).
    """
    # Guard against non‑string input
    if not isinstance(path, str):
        return ''
    if path == '':
        return ''
    # Split on '/', ignore empty components caused by consecutive slashes
    parts = path.split('/')
    stack = []
    for part in parts:
        if part == '' or part == '.':
            # Skip empty components and current‑directory references
            continue
        if part == '..':
            if stack:
                stack.pop()
            # If stack empty we stay at root, so just ignore
            continue
        # Normal directory name
        stack.append(part)
    # Build the simplified path
    if not stack:
        return '/'  # root
    return '/' + '/'.join(stack)

