def solve(s):
    """Return True if brackets in s are balanced and properly nested.
    Considers (), [], {}. Ignores other characters.
    """
    stack = []
    opening = set('([{')
    matching = {')': '(', ']': '[', '}': '{'}
    for ch in s:
        if ch in opening:
            stack.append(ch)
        elif ch in matching:
            if not stack or stack[-1] != matching[ch]:
                return False
            stack.pop()
    return not stack

