def solve(intervals):
    # Ensure each interval is ordered (start <= end)
    norm = [sorted(iv) for iv in intervals]
    if not norm:
        return []
    # Sort by start
    norm.sort(key=lambda x: x[0])
    merged = [norm[0][:]]
    for cur in norm[1:]:
        last = merged[-1]
        if cur[0] <= last[1]:
            # Merge overlapping or touching intervals
            last[1] = max(last[1], cur[1])
        else:
            merged.append(cur[:])
    return merged

